package com.lqq.supportflow.model.infrastructure.protocol;
import com.fasterxml.jackson.databind.JsonNode; import com.lqq.supportflow.model.domain.*; import java.time.Duration; import java.util.*; import org.springframework.http.HttpHeaders; import org.springframework.stereotype.Component; import org.springframework.web.reactive.function.client.WebClient;
@Component public class OpenAiCompatibleEmbeddingGateway implements EmbeddingGateway { private final ModelConfigPort configs; private final ModelSecretPort secrets; private final WebClient client; public OpenAiCompatibleEmbeddingGateway(ModelConfigPort configs,ModelSecretPort secrets,WebClient.Builder builder){this.configs=configs;this.secrets=secrets;this.client=builder.build();} public List<float[]> embedBatch(EmbeddingRequest request){EmbeddingModelConfig config=configs.findDefaultEmbedding(request.tenantId()).orElseThrow(()->new IllegalArgumentException("default OpenAI-compatible embedding model is not configured"));JsonNode response=client.post().uri(stripTrailingSlash(config.baseUrl())+"/embeddings").header(HttpHeaders.AUTHORIZATION,"Bearer "+secrets.decrypt(config.encryptedApiKey())).bodyValue(Map.of("model",config.modelName(),"input",request.inputs())).retrieve().bodyToMono(JsonNode.class).block(Duration.ofSeconds(30));if(response==null||!response.has("data"))throw new IllegalArgumentException("embedding response is invalid");List<float[]> vectors=new ArrayList<>();for(JsonNode entry:response.path("data")){float[] vector=new float[entry.path("embedding").size()];for(int index=0;index<vector.length;index++)vector[index]=(float)entry.path("embedding").get(index).asDouble();vectors.add(vector);}if(vectors.size()!=request.inputs().size())throw new IllegalArgumentException("embedding response count does not match input count");return vectors;} private String stripTrailingSlash(String url){return url.endsWith("/")?url.substring(0,url.length()-1):url;}}
